G=nx.Graph();G.add_nodes_from(valid)
for c,r in valid:
 for dc,dr in [(1,0),(0,1)]:
  if (c+dc,r+dr) in valid:G.add_edge((c,r),(c+dc,r+dr))
S=(4,7); T1=(1,2); T2=(6,9); R=(8,8); Goal=(1,7)
for target in [T1,T2,R,Goal]:
 try:
  p=nx.shortest_path(G,S,target);print('S->',target,'len',len(p)-1,p)
 except:print('unreachable',target)
# shortest to neighbor of T1
print('T1 neighbors',list(G.neighbors(T1)))
for n in G.neighbors(T1):
 p=nx.shortest_path(G,S,n);print(n,len(p)-1,p)
